(function(){'use strict';
const el=id=>document.getElementById(id),money=amount=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(amount);
const sales=el('estimated-sales'),rate=el('calculated-rate'),commission=el('calculated-commission'),explanation=el('calculated-explanation'),bonus=el('calculated-bonus');
function calculate(){const n=Math.max(0,Math.min(100000000,Math.round(Number(sales.value)||0)));const t=n>=1000000?30:n>=500000?25:20;const earned=Math.round(n*t/100),base=Math.round(n*.2);rate.textContent=t+'%';commission.textContent=money(earned);explanation.textContent=money(n)+' eligible annual sales × '+t+'%';bonus.textContent=t>20?'Includes '+money(earned-base)+' additional annual tier benefit compared with the 20% starter rate.':'At the starter rate; milestone upgrades apply once qualified and verified.';}
sales.addEventListener('input',calculate);calculate();
const form=el('partner-application'),status=el('application-availability'),result=el('partner-application-result'),submit=el('partner-submit'),offline=el('partner-offline');let challenge='';
async function availability(){try{const r=await fetch('/api/partners/config',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok||!d.enabled||!d.challenge){status.textContent='Partner applications are not enabled on this preview.';offline.hidden=false;form.hidden=true;return}challenge=d.challenge;status.textContent='Applications open for manual review · No joining fee';form.hidden=false;offline.hidden=true;}catch{status.textContent='Application service is unavailable.';offline.hidden=false;form.hidden=true}}
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity()||!challenge)return;const data=new FormData(form);
const payload={contact_name:String(data.get('contact_name')||''),email:String(data.get('email')||''),organisation:String(data.get('organisation')||''),region:String(data.get('region')||''),role:String(data.get('role')||''),channel:String(data.get('channel')||''),experience:String(data.get('experience')||''),consent:data.get('consent')==='on',independence_confirmed:data.get('independence_confirmed')==='on',website:String(data.get('website')||''),challenge};
submit.disabled=true;result.textContent='Submitting for review…';
try{const r=await fetch('/api/partners/apply',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(12000)});const body=await r.json();if(!r.ok)throw Error(body.error||'Could not submit application');form.reset();form.hidden=true;status.textContent='Application submitted for review';result.textContent='';offline.hidden=false;offline.innerHTML='Thank you. Your expression of interest has been submitted for manual review. Your reference is <strong></strong>. This is not an approved partner account or a referral code.';offline.querySelector('strong').textContent=body.reference||'confirmed';}
catch(error){result.textContent=error.message+'. Your entries remain in the form.';if(/expired|quickly/i.test(error.message))await availability();}
finally{submit.disabled=false}});
availability();
})();